 \t\t\t// encounter.observations[0-n].patient\n134: \n135: \t\t\t// If we are changing encounter.encounterDatetime, then we need to\n136: \t\t\t// also apply that\n137: \t\t\t// to Obs that inherited their obsDatetime from the encounter in the\n138: \t\t\t// first place\n139: \n140: \t\t\tDate newDate = encounter.getEncounterDatetime();\n141: \t\t\tLocation newLocation = encounter.getLocation();\n142: \t\t\tfor (Obs obs : encounter.getAllFlattenedObs(true)) {\n143: \t\t\t\t// if the date was changed\n144: \t\t\t\tif (OpenmrsUtil.compare(originalDate, newDate) != 0\n145: \t\t\t\t        && OpenmrsUtil.compare(obs.getObsDatetime(), originalDate) == 0) {\n146: \n147: \t\t\t\t\t// if the obs datetime is the same as the\n148: \t\t\t\t\t// original encounter datetime, fix it\n149: \t\t\t\t\tobs.setObsDatetime(newDate);\n150: \n151: \t\t\t\t}\n152: \n153: \t\t\t\tif (!OpenmrsUtil.nullSafeEquals(newLocation, originalLocation)\n154: \t\t\t\t        && obs.getLocation().equals(originalLocation)) {\n155: \t\t\t\t\tobs.setLocation(newLocation);\n156: \t\t\t\t}\n157: \n158: \t\t\t\t// if the Person in the obs doesn't match the Patient in the\n159: \t\t\t\t// encounter, fix it\n160: \t\t\t\tif (!obs.getPerson().getPersonId().equals(p.getPatientId())) {\n161: \t\t\t\t\tobs.setPerson(p);\n162: \t\t\t\t}\n163: \t\t\t}\n164: \t\t}\n165: \t\t// same goes for Orders\n166: \t\tfor (Order o : encounter.getOrders()) {\n167: \t\t\tif (!p.equals(o.getPatient())) {\n168: \t\t\t\to.setPatient(p);\n169: \t\t\t}\n170: \t\t}\n171: \n172: \t\t// do the actual saving to the database\n173: \t\tdao.saveEncounter(encounter);\n174: \n175: \t\t// save the new orderGroups\n\n(Showing lines 96-175 of 1032. Use offset=176 to continue.)\n</content>"}]}]},"parent_tool_use_id":null,"session_id":"b38238b1-9f13-46f0-93e4-511bbb558fee","uuid":"f99cc4ce-3147-4d8e-8d26-97f339fea0a7","timestamp":"2026-10-19T17:56:55.305Z","tool_use_result":[{"type":"text","text":"<repo>github.com/openmrs/openmrs-core</repo>\n<path